function b=v4TrackAEightUpConsensusBootstrap(packet,c,step,maxRate)
s=packet.schedule;m=c.samplesPerSymbol;n=0:m-1;down=conj(v4ModulateSymbol(0,c));time=s.centerTimeOffsetSec(1:8);cfo=zeros(8,1);ratio=zeros(8,1);
for k=1:8,first=s.startSample(k)+1;x=packet.rx(first:first+m-1).';z=fft(x.*down);[~,q]=max(abs(z).^2);q=q-1;if q>=m/2,q=q-m;end;e=v4PhaseRotationEstimate(x,0,c,(q-1:step:q+1).');cfo(k)=e.offsetBins;ratio(k)=e.peakRatio;end
weight=min(4,max(1,ratio));bestScore=-Inf;bestRate=0;bestCenter=median(cfo);bestResidual=Inf;
for i=1:7,for j=i+1:8,rate=(cfo(j)-cfo(i))/(time(j)-time(i));if abs(rate)>maxRate,continue,end;center=cfo(j)+rate*(time-time(j));residual=abs(cfo-center);score=sum(weight.*exp(-0.5*(residual/0.35).^2));tie=sum(residual);if score>bestScore||(abs(score-bestScore)<1e-12&&tie<bestResidual),bestScore=score;bestRate=rate;bestCenter=cfo(j)-rate*time(j);bestResidual=tie;end;end,end
residual=abs(cfo-(bestCenter+bestRate*time));inlier=residual<=0.6;if sum(inlier)>=2,x=time(inlier);y=cfo(inlier);w=sqrt(weight(inlier));beta=([ones(size(x)) x].*w)\(y.*w);for iter=1:2,r=y-[ones(size(x)) x]*beta;rw=min(1,0.25./max(abs(r),eps));ww=sqrt(weight(inlier).*rw);beta=([ones(size(x)) x].*ww)\(y.*ww);end;intercept=beta(1);rate=beta(2);else,rate=bestRate;intercept=bestCenter;end;target=10*c.symbolDurationSec;b=struct('cfoBins',cfo,'peakRatio',ratio,'measurementTimeSec',time,'rateBinsPerSec',rate,'cfoAtQuarterStartBins',intercept+rate*target,'availableAtSec',8*c.symbolDurationSec,'inlierMask',inlier,'consensusScore',bestScore,'stepBins',step,'usesTruth',false,'fitMethod','quality-weighted-pair-consensus-huber');
end
